import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"9.13 问题速查","description":"","frontmatter":{"title":"9.13 问题速查"},"headers":[],"relativePath":"ch09/13.md","filePath":"ch09/13.md","lastUpdated":1789497795000}'),r={name:"ch09/13.md"};function a(n,t,s,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="_9-13-问题速查" tabindex="-1">9.13 问题速查 <a class="header-anchor" href="#_9-13-问题速查" aria-label="Permalink to &quot;9.13 问题速查&quot;">​</a></h1><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>编译报“找不到符号 <code>MockMvc</code>”</td><td>少了 <code>spring-boot-starter-webmvc-test</code></td><td>补测试 starter 依赖</td></tr><tr><td><code>@WebMvcTest</code> import 不到</td><td>4.x 换了包</td><td>用 <code>org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest</code></td></tr><tr><td><code>@DataJpaTest</code> import 不到</td><td>4.x 换了包</td><td>用 <code>org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest</code></td></tr><tr><td><code>@MockBean</code> 编译不过</td><td>4.x 已删除该注解</td><td>改用 <code>@MockitoBean</code> / <code>@MockitoSpyBean</code></td></tr><tr><td>切片测试里 Service 注入为 null</td><td>切片不扫描 <code>@Service</code></td><td>用 <code>@MockitoBean</code> 补假对象</td></tr><tr><td>切片测试想连数据库连不上</td><td><code>@WebMvcTest</code> 不含数据层</td><td>换成 <code>@DataJpaTest</code> 或 <code>@SpringBootTest</code></td></tr><tr><td>想在一个测试里用两个切片注解</td><td>不支持混用</td><td>选一个 <code>@...Test</code>，其余用 <code>@AutoConfigure...</code> 补</td></tr><tr><td>参数校验失败返回 500 而不是 400</td><td><code>@RestControllerAdvice</code> 没被扫描到</td><td>检查它是否在切片的扫描范围内</td></tr><tr><td><code>.extractingPath(...)</code> 链式写两遍编译不过</td><td>返回的是值断言，不是内容断言</td><td>先把 <code>bodyJson()</code> 的结果存下来，再逐个提取</td></tr><tr><td><code>TestRestTemplate</code> 找不到类</td><td>4.x 搬了模块和包</td><td>引 <code>spring-boot-resttestclient</code>，用 <code>org.springframework.boot.resttestclient.TestRestTemplate</code></td></tr><tr><td><code>TestRestTemplate</code> 注入不进来</td><td>少 <code>spring-boot-restclient</code></td><td>补上（官方文档明确要求）</td></tr><tr><td>真实端口测试数据没回滚</td><td>请求与测试在不同线程、不同事务</td><td>用例自己保证数据唯一并清理</td></tr><tr><td>端口固定导致测试互相抢</td><td>用了 <code>DEFINED_PORT</code></td><td>换 <code>RANDOM_PORT</code> + <code>@LocalServerPort</code></td></tr><tr><td>编译报找不到 <code>MySQLContainer</code></td><td>2.0 把数据库容器移出了 core</td><td>引 <code>org.testcontainers:testcontainers-mysql</code></td></tr><tr><td><code>MySQLContainer</code> 泛型用法编译不过</td><td>2.0 去掉了自引用泛型</td><td>不要写 <code>MySQLContainer&lt;&gt;</code>，直接 <code>new MySQLContainer(“mysql:8”)</code></td></tr><tr><td>升了 Boot 但 Testcontainers 还是 1.21</td><td>老坐标不会自动跟着升</td><td>把 <code>org.testcontainers:mysql</code> 换成 <code>testcontainers-mysql</code></td></tr><tr><td>Testcontainers 卡在 <code>Retrying pull for ryuk</code></td><td>拉不到 <code>testcontainers/ryuk</code></td><td>配镜像加速器，或临时 <code>TESTCONTAINERS_RYUK_DISABLED=true</code></td></tr><tr><td>容器被停掉后连接报错</td><td>容器由 Testcontainers 管，关闭顺序无保证</td><td>改成容器 Bean（Spring 管生命周期）</td></tr><tr><td><code>@ServiceConnection</code> 不生效</td><td>用了 <code>GenericContainer</code> 但没写名字</td><td><code>@ServiceConnection(name = “mysql”)</code></td></tr><tr><td>H2 能跑、MySQL 报错</td><td>方言/字符集/约束差异</td><td>这类用例放到 Testcontainers 层</td></tr></tbody></table><hr>',3)])])}const m=d(r,[["render",a]]);export{_ as __pageData,m as default};
